import{_ as e,o as s,c as i,a3 as a}from"./chunks/framework.Cr9EE2ob.js";const g=JSON.parse('{"title":"Mail client autoconfiguration","description":"yarilo-autoconfig tells Thunderbird and Outlook which hosts and ports to use for an address: what it serves, how to deploy it, the DNS records a domain publishes, and which clients still need manual setup.","frontmatter":{"description":"yarilo-autoconfig tells Thunderbird and Outlook which hosts and ports to use for an address: what it serves, how to deploy it, the DNS records a domain publishes, and which clients still need manual setup.","head":[["meta",{"name":"robots","content":"noindex"}],["link",{"rel":"canonical","href":"https://doc.yarilomail.org/latest/installation/autoconfig.html"}],["meta",{"property":"og:url","content":"https://doc.yarilomail.org/main/installation/autoconfig.html"}],["meta",{"property":"og:title","content":"Mail client autoconfiguration"}],["meta",{"name":"twitter:title","content":"Mail client autoconfiguration"}],["meta",{"property":"og:description","content":"yarilo-autoconfig tells Thunderbird and Outlook which hosts and ports to use for an address: what it serves, how to deploy it, the DNS records a domain publishes, and which clients still need manual setup."}],["meta",{"name":"twitter:description","content":"yarilo-autoconfig tells Thunderbird and Outlook which hosts and ports to use for an address: what it serves, how to deploy it, the DNS records a domain publishes, and which clients still need manual setup."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@graph\\":[{\\"@type\\":\\"TechArticle\\",\\"@id\\":\\"https://doc.yarilomail.org/main/installation/autoconfig.html#article\\",\\"mainEntityOfPage\\":\\"https://doc.yarilomail.org/main/installation/autoconfig.html\\",\\"headline\\":\\"Mail client autoconfiguration\\",\\"description\\":\\"yarilo-autoconfig tells Thunderbird and Outlook which hosts and ports to use for an address: what it serves, how to deploy it, the DNS records a domain publishes, and which clients still need manual setup.\\",\\"dateModified\\":\\"2026-10-24T22:06:22.000Z\\",\\"inLanguage\\":\\"en\\",\\"isPartOf\\":{\\"@id\\":\\"https://doc.yarilomail.org/#website\\"},\\"publisher\\":{\\"@id\\":\\"https://yarilomail.org/#organization\\"}},{\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Yarilo documentation\\",\\"item\\":\\"https://doc.yarilomail.org/main/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Mail client autoconfiguration\\",\\"item\\":\\"https://doc.yarilomail.org/main/installation/autoconfig.html\\"}]}]}"]]},"headers":[],"relativePath":"installation/autoconfig.md","filePath":"installation/autoconfig.md","lastUpdated":1792879582000}'),o={name:"installation/autoconfig.md"};function n(l,t,r,d,h,c){return s(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="mail-client-autoconfiguration" tabindex="-1">Mail client autoconfiguration <a class="header-anchor" href="#mail-client-autoconfiguration" aria-label="Permalink to &quot;Mail client autoconfiguration&quot;">​</a></h1><p><code>yarilo-autoconfig</code> tells a mail client which hosts and ports to use for an address, so the user types only the address and the password. It answers two formats:</p><ul><li>the autoconfig XML that Thunderbird (desktop and Android) and FairEmail read;</li><li>the POX Autodiscover answer that classic Outlook for Windows reads.</li></ul><p>It is a separate service with its own <a href="https://github.com/yarilomail/yarilo-autoconfig" target="_blank" rel="noreferrer">repository</a>, image and Helm chart. It does not talk to yarilo and keeps no list of domains: every address gets the same hosts from its configuration, and addresses are never looked up, so the service cannot be used to find out which mailboxes exist.</p><h2 id="which-clients-configure-themselves" tabindex="-1">Which clients configure themselves <a class="header-anchor" href="#which-clients-configure-themselves" aria-label="Permalink to &quot;Which clients configure themselves&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Client</th><th style="text-align:left;">How it finds the settings</th></tr></thead><tbody><tr><td style="text-align:left;">Thunderbird, Thunderbird for Android</td><td style="text-align:left;">the domain&#39;s MX record, then <code>autoconfig.</code> on the MX domain</td></tr><tr><td style="text-align:left;">FairEmail</td><td style="text-align:left;">the same autoconfig XML, and RFC 6186 SRV records</td></tr><tr><td style="text-align:left;">Outlook (classic, Windows)</td><td style="text-align:left;">the <code>_<wbr>autodiscover.<wbr>_<wbr>tcp</code> SRV record, after one confirmation prompt</td></tr><tr><td style="text-align:left;">New Outlook for Windows, Outlook mobile</td><td style="text-align:left;">manual setup</td></tr><tr><td style="text-align:left;">Gmail app, Samsung Email</td><td style="text-align:left;">manual setup</td></tr><tr><td style="text-align:left;">Apple Mail (iOS, iPadOS, macOS)</td><td style="text-align:left;">manual setup</td></tr></tbody></table><p>Users of the clients marked manual enter the IMAP and SMTP hosts and ports from the <a href="#settings">settings</a> themselves.</p><h2 id="choosing-the-host-names" tabindex="-1">Choosing the host names <a class="header-anchor" href="#choosing-the-host-names" aria-label="Permalink to &quot;Choosing the host names&quot;">​</a></h2><p>Thunderbird reaches the service only through the domain&#39;s MX record. It takes the first MX host, drops its first label and asks <code>autoconfig.</code> on what is left. With MX <code>mx.<wbr>example.<wbr>net</code> the service must answer at <code>autoconfig.<wbr>example.<wbr>net</code>:</p><ul><li>renaming <code>mx</code> to <code>mx01</code> changes nothing;</li><li>moving the MX under another domain moves the autoconfig host with it.</li></ul><p>A domain whose first MX is not yours, such as a third-party spam filter, sends Thunderbird to that provider instead and gets no autoconfiguration.</p><p>Outlook reaches the service through an SRV record that points at <code>autodiscover.</code> on your domain, so serve both names:</p><ul><li><code>autoconfig.<wbr>example.<wbr>net</code></li><li><code>autodiscover.<wbr>example.<wbr>net</code></li></ul><h2 id="deploying-the-service" tabindex="-1">Deploying the service <a class="header-anchor" href="#deploying-the-service" aria-label="Permalink to &quot;Deploying the service&quot;">​</a></h2><p>Install the chart from the repository, with the two hosts every answer points at:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/yarilomail/yarilo-autoconfig.git</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">helm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yarilo-autoconfig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./yarilo-autoconfig/helm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.imap_host=imap.example.net</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.smtp_host=smtp.example.net</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ingress.enabled=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ingress.tlsSecretName=autoconfig-tls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ingress.hosts={autoconfig.example.net,autodiscover.example.net}&#39;</span></span></code></pre></div><p>This installs:</p><ul><li>two replicas of the service, with a PodDisruptionBudget;</li><li>an Ingress for both hosts, serving the certificate in <code>autoconfig-tls</code>;</li><li>health and metrics on a separate port that the Ingress does not expose.</li></ul><p>The chart refuses to render without <code>config.<wbr>imap_<wbr>host</code> and <code>config.<wbr>smtp_<wbr>host</code>. The service itself refuses to start on an invalid value and lists every problem in its log.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Each key under <code>config:</code> in the chart becomes the environment variable of the same name in upper case (<code>imap_<wbr>host</code> becomes <code>IMAP_<wbr>HOST</code>). An empty value keeps the default.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Value</th><th style="text-align:left;">Default</th><th style="text-align:left;">Meaning</th></tr></thead><tbody><tr><td style="text-align:left;"><code>config.<wbr>imap_<wbr>host</code></td><td style="text-align:left;">none</td><td style="text-align:left;">IMAP host, implicit TLS (required)</td></tr><tr><td style="text-align:left;"><code>config.<wbr>imap_<wbr>port</code></td><td style="text-align:left;"><code>993</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>config.<wbr>smtp_<wbr>host</code></td><td style="text-align:left;">none</td><td style="text-align:left;">submission host (required)</td></tr><tr><td style="text-align:left;"><code>config.<wbr>smtp_<wbr>implicit_<wbr>tls_<wbr>port</code></td><td style="text-align:left;"><code>465</code></td><td style="text-align:left;"><code>0</code> = not offered</td></tr><tr><td style="text-align:left;"><code>config.<wbr>smtp_<wbr>starttls_<wbr>port</code></td><td style="text-align:left;"><code>587</code></td><td style="text-align:left;"><code>0</code> = not offered</td></tr><tr><td style="text-align:left;"><code>config.<wbr>pop3_<wbr>host</code></td><td style="text-align:left;">empty</td><td style="text-align:left;">empty = POP3 not offered</td></tr><tr><td style="text-align:left;"><code>config.<wbr>pop3_<wbr>port</code></td><td style="text-align:left;"><code>995</code></td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;"><code>config.<wbr>display_<wbr>name</code></td><td style="text-align:left;"><code>Mail</code></td><td style="text-align:left;">provider name the client shows</td></tr><tr><td style="text-align:left;"><code>config.<wbr>dav_<wbr>url</code></td><td style="text-align:left;">empty</td><td style="text-align:left;">target of the <code>/<wbr>.<wbr>well-known/<wbr>caldav</code> and <code>/<wbr>.<wbr>well-known/<wbr>carddav</code> redirects</td></tr><tr><td style="text-align:left;"><code>config.<wbr>jmap_<wbr>url</code></td><td style="text-align:left;">empty</td><td style="text-align:left;">target of the <code>/<wbr>.<wbr>well-known/<wbr>jmap</code> redirect</td></tr><tr><td style="text-align:left;"><code>logLevel</code></td><td style="text-align:left;">empty</td><td style="text-align:left;"><code>debug</code> logs each answer with its domain, never the address</td></tr></tbody></table><p>Submission with implicit TLS is offered before STARTTLS, as RFC 8314 recommends. Thunderbird gets both, port 465 first. Outlook takes a single SMTP entry: 465, or 587 when implicit TLS is off. IMAP and POP3 are offered with implicit TLS only.</p><p>The <code>.<wbr>well-known</code> redirects are a convenience for a user who types the autoconfig host into a calendar or JMAP client. Real discovery for those protocols uses SRV records pointing at the services themselves.</p><h2 id="dns-records-for-a-mail-domain" tabindex="-1">DNS records for a mail domain <a class="header-anchor" href="#dns-records-for-a-mail-domain" aria-label="Permalink to &quot;DNS records for a mail domain&quot;">​</a></h2><p>Every domain whose users should be configured automatically publishes these records. Replace <code>customer.<wbr>example</code> with the mail domain and <code>example.<wbr>net</code> with your provider domain:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>customer.example.                     IN  MX   10 mx.example.net.</span></span>
<span class="line"><span>_autodiscover._tcp.customer.example.  IN  SRV  0 0 443 autodiscover.example.net.</span></span>
<span class="line"><span>_imaps._tcp.customer.example.         IN  SRV  0 1 993 imap.example.net.</span></span>
<span class="line"><span>_submissions._tcp.customer.example.   IN  SRV  0 1 465 smtp.example.net.</span></span>
<span class="line"><span>_submission._tcp.customer.example.    IN  SRV  10 1 587 smtp.example.net.</span></span></code></pre></div><p>These records:</p><ul><li>let Thunderbird find <code>autoconfig.<wbr>example.<wbr>net</code> through the MX;</li><li>send Outlook to <code>autodiscover.<wbr>example.<wbr>net</code>;</li><li>give RFC 6186 clients the IMAP and submission hosts, with implicit TLS preferred.</li></ul><div class="warning custom-block"><p class="custom-block-title">No autodiscover host on the mail domain</p><p>Do not create <code>autodiscover.<wbr>customer.<wbr>example</code> in any form, including a wildcard record. Outlook tries that name before the SRV record, stops at the certificate error it gets there and never reads the SRV record.</p></div><p>Outlook shows a prompt the first time it follows the SRV record to another domain, asking whether to let <code>autodiscover.<wbr>example.<wbr>net</code> configure the account. That prompt is expected.</p><p>See <a href="/main/installation/dns.html">DNS for a mail domain</a> for the records every mail domain needs regardless of autoconfiguration.</p><h2 id="verifying" tabindex="-1">Verifying <a class="header-anchor" href="#verifying" aria-label="Permalink to &quot;Verifying&quot;">​</a></h2><p>Fetch the Thunderbird answer the way Thunderbird does:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://autoconfig.example.net/mail/config-v1.1.xml?emailaddress=alice@customer.example&#39;</span></span></code></pre></div><p>Fetch the Outlook answer:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://autodiscover.example.net/autodiscover/autodiscover.xml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: text/xml&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;Autodiscover xmlns=&quot;http://schemas.microsoft.com/exchange/autodiscover/outlook/requestschema/2006&quot;&gt;&lt;Request&gt;&lt;EMailAddress&gt;alice@customer.example&lt;/EMailAddress&gt;&lt;AcceptableResponseSchema&gt;http://schemas.microsoft.com/exchange/autodiscover/outlook/responseschema/2006a&lt;/AcceptableResponseSchema&gt;&lt;/Request&gt;&lt;/Autodiscover&gt;&#39;</span></span></code></pre></div><p>Check the records of a mail domain:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> MX</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> customer.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SRV</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> _autodiscover._tcp.customer.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dig</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> A</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> autodiscover.customer.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +short</span></span></code></pre></div><p>The last command must return nothing.</p>`,40)])])}const m=e(o,[["render",n]]);export{g as __pageData,m as default};
